    <nav class="mb-5 flex gap-2 overflow-x-auto">@foreach(['Basic Information','Trigger','Steps','Review'] as $i=>$label)<button type="button" class="btn-secondary shrink-0" :class="section==={{$i+1}} && 'ring-2 ring-emerald-500'" @click="section={{$i+1}}">{{$i+1}}. {{$label}}</button>@endforeach</nav>
