        <div class="card"><div class="flex flex-wrap gap-2"><template x-for="type in addTypes" :key="type.value"><button type="button" class="btn-secondary" @click="add(type.value)" x-text="'+ '+type.label"></button></template></div></div>
        <template x-for="(step,index) in steps" :key="step.step_key"><article class="card"><div class="flex flex-wrap items-center gap-2"><span class="grid size-8 place-items-center rounded-lg bg-[var(--accent-soft)] font-bold text-[var(--accent)]" x-text="index+1"></span><strong class="flex-1" x-text="label(step.step_type)"></strong><button type="button" class="btn-secondary" @click="move(index,-1)" :disabled="index===0">Up</button><button type="button" class="btn-secondary" @click="move(index,1)" :disabled="index===steps.length-1">Down</button><button type="button" class="btn-secondary text-red-500" @click="remove(index)">Remove</button></div>
