                <template x-if="step.step_type==='branch'"><div class="contents"><label>True path<select class="input mt-2" x-model="step.configuration.true_step_key"><option value="">Select step</option><template x-for="target in steps.filter(x=>x.step_key!==step.step_key)" :key="target.step_key"><option :value="target.step_key" x-text="target.name||label(target.step_type)"></option></template></select></label><label>False path<select class="input mt-2" x-model="step.configuration.false_step_key"><option value="">Select step</option><template x-for="target in steps.filter(x=>x.step_key!==step.step_key)" :key="target.step_key"><option :value="target.step_key" x-text="target.name||label(target.step_type)"></option></template></select></label></div></template>
