                <label x-show="step.step_type==='action' && ['add_contact_label','remove_contact_label'].includes(step.configuration.action_type)">Label<select class="input mt-2" x-model="step.configuration.parameters.label_uuid"><option value="">Select label</option>@foreach($labels as $label)<option value="{{$label->uuid}}">{{$label->name}}</option>@endforeach</select></label>
                <label x-show="step.step_type==='action' && ['add_contact_to_group','remove_contact_from_group'].includes(step.configuration.action_type)">Group<select class="input mt-2" x-model="step.configuration.parameters.group_uuid"><option value="">Select group</option>@foreach($groups as $group)<option value="{{$group->uuid}}">{{$group->name}}</option>@endforeach</select></label>
