    <section x-show="section===4" class="card space-y-4"><h2 class="font-semibold">Review</h2><dl class="grid gap-3 sm:grid-cols-3"><div><dt class="text-[var(--text-muted)]">Trigger</dt><dd>Manual</dd></div><div><dt class="text-[var(--text-muted)]">Steps</dt><dd x-text="steps.length"></dd></div><div><dt class="text-[var(--text-muted)]">State</dt><dd>Saved as draft</dd></div></dl><p class="rounded-xl border border-amber-500/30 bg-amber-500/5 p-4 text-sm">Publishing validates resource ownership, graph paths, template versions, consent-aware actions, and safety limits.</p><button class="btn-primary">{{ isset($workflow) ? 'Save changes' : 'Create workflow' }}</button></section>
