</form>
<script>
document.addEventListener('alpine:init',()=>Alpine.data('automationBuilder',(initial,templates)=>({section:1,templates,steps:initial.map(s=>({...s,uiField:Object.keys(s.configuration?.parameters?.updates||{})[0]||'company',uiValue:Object.values(s.configuration?.parameters?.updates||{})[0]?.value||''})),payload:[],addTypes:[{value:'condition',label:'Condition'},{value:'branch',label:'Branch'},{value:'delay',label:'Delay'},{value:'send_whatsapp_template',label:'Send template'},{value:'add_contact_label',label:'Add label'},{value:'remove_contact_label',label:'Remove label'},{value:'add_contact_to_group',label:'Add group'},{value:'remove_contact_from_group',label:'Remove group'},{value:'update_contact',label:'Update contact'},{value:'stop',label:'Stop'}],label(v){return v.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())},condition(){return{type:'group',version:1,logic:'and',children:[{type:'rule',field:'trigger.type',operator:'equals',value:'manual'}]}},add(type){let key='step_'+crypto.randomUUID().replaceAll('-','').slice(0,12),stepType=['condition','branch','delay','stop'].includes(type)?type:'action',configuration={};if(stepType==='condition')configuration={condition:this.condition(),next_step_key:''};if(stepType==='branch')configuration={condition:this.condition(),true_step_key:'',false_step_key:''};if(stepType==='delay')configuration={delay_type:'duration',seconds:60,next_step_key:''};if(stepType==='action'){configuration={action_type:type,parameters:{},next_step_key:''};if(type==='send_whatsapp_template')configuration.parameters={template_uuid:'',session_strategy:'automatic',session_uuid:null,variable_mappings:{}};if(type.includes('label'))configuration.parameters={label_uuid:''};if(type.includes('group'))configuration.parameters={group_uuid:''};if(type==='update_contact')configuration.parameters={updates:{}}}this.steps.push({step_key:key,parent_step_key:null,step_type:stepType,position:this.steps.length+1,name:this.label(type),configuration,uiField:'company',uiValue:''})},remove(i){this.steps.splice(i,1)},move(i,d){let j=i+d;if(j<0||j>=this.steps.length)return;[this.steps[i],this.steps[j]]=[this.steps[j],this.steps[i]]},templateChanged(step){let vars=this.templates[step.configuration.parameters.template_uuid]?.variables||[];step.configuration.parameters.variable_mappings={};vars.forEach(k=>step.configuration.parameters.variable_mappings[k]={source:'contact',key:k})},prepare(){this.payload=this.steps.map((s,i)=>{let c=structuredClone(s.configuration);if(s.step_type==='action'&&c.action_type==='update_contact')c.parameters.updates={[s.uiField]:{source:'constant',value:s.uiValue}};return{step_key:s.step_key,parent_step_key:i?this.steps[i-1].step_key:null,step_type:s.step_type,position:i+1,name:s.name,configuration:c}})}})))
</script>
</x-layouts.app>
